    input.dispatchEvent(new window.Event('input', { bubbles: true }));
    await new Promise((r) => setTimeout(r, 300));
    assert(document.querySelectorAll('#course-grid .course-card').length === 1, 'search calculus returns 1');
    assert(document.querySelector('#results-status').textContent.includes('1 of 18'), 'status count updates');
    input.value = '';
    const dept = document.querySelector('#filter-department');
    dept.value = 'Computer Science';
    dept.dispatchEvent(new window.Event('change', { bubbles: true }));
    await new Promise((r) => setTimeout(r, 50));
    assert(document.querySelectorAll('#course-grid .course-card').length === 4, 'CSE dept returns 4');
    const avail = document.querySelector('#filter-availability');
    avail.value = 'full';
    avail.dispatchEvent(new window.Event('change', { bubbles: true }));
    await new Promise((r) => setTimeout(r, 50));
    assert(document.querySelectorAll('#course-grid .course-card').length === 1, 'full CSE returns 1');
    document.querySelector('#reset-filters').click();
    await new Promise((r) => setTimeout(r, 50));
    assert(document.querySelectorAll('#course-grid .course-card').length === 18, 'reset returns 18');
    console.log('CATALOG OK, errors:', errors);
    await runAxe('catalog', window);
  }

  // REGISTER
  {
    const { window, document, errors } = await loadPage('register.html');
    assert(document.querySelector('#reg-name').value === 'Jordan Rivera', 'registration prefills name');
    assert(document.querySelector('#reg-email').value === 'jordan.rivera@northbridge.edu', 'registration prefills email');
    // validation
    const name = document.querySelector('#reg-name');
    name.value = '';
    document.querySelector('#registration-form').dispatchEvent(new window.Event('submit', { bubbles: true, cancelable: true }));
    await new Promise((r) => setTimeout(r, 20));
    assert(!document.querySelector('#error-summary').hidden, 'error summary shows');
    assert(document.activeElement === document.querySelector('#error-summary'), 'focus moves to error summary');
    assert(document.querySelector('#reg-name').getAttribute('aria-invalid') === 'true', 'invalid name marked');
    assert(document.querySelectorAll('#error-summary-list li').length >= 1, 'summary lists error');
    // duplicate
    name.value = 'Jordan Rivera';
    name.dispatchEvent(new window.Event('input', { bubbles: true }));
    const course = document.querySelector('#reg-course');
    course.value = 'PSY 101';
    course.dispatchEvent(new window.Event('change', { bubbles: true }));
    document.querySelector('#registration-form').dispatchEvent(new window.Event('submit', { bubbles: true, cancelable: true }));
    await new Promise((r) => setTimeout(r, 20));
    assert(document.querySelector('#reg-course-error').textContent.includes('already registered'), 'duplicate detected');
    // success
    course.value = 'CSE 216';
    course.dispatchEvent(new window.Event('change', { bubbles: true }));
    document.querySelector('#registration-form').dispatchEvent(new window.Event('submit', { bubbles: true, cancelable: true }));
    await new Promise((r) => setTimeout(r, 20));
    const dialog = document.querySelector('#confirm-dialog');
    assert(dialog.hasAttribute('open'), 'confirm dialog opens');
    assert(document.activeElement === document.querySelector('#confirm-cancel'), 'cancel focused in dialog');
    assert(document.querySelector('#confirm-summary').textContent.includes('CSE 216'), 'dialog summarizes course');
    document.querySelector('#confirm-submit').click();
    await new Promise((r) => setTimeout(r, 20));
    assert(!dialog.hasAttribute('open'), 'dialog closes after confirm');
    assert(document.querySelector('#reg-status').textContent.includes('CSE 216'), 'success status shown');
    const saved = JSON.parse(window.localStorage.getItem('nbu-registration-v1'));
    assert(saved.registrations.includes('CSE 216'), 'registration persisted');
    console.log('REGISTER OK, errors:', errors);
    await runAxe('register', window);
  }

  // PROFILE
  {
    const { window, document, errors } = await loadPage('profile.html');
    assert(document.querySelectorAll('#registered-tbody tr').length === 2, 'profile table has 2 rows');
    assert(document.querySelector('#registered-caption').textContent.includes('2 courses'), 'caption count');
    // invalid profile save
    const name = document.querySelector('#profile-name-input');
    name.value = '';
    document.querySelector('#profile-form').dispatchEvent(new window.Event('submit', { bubbles: true, cancelable: true }));
    await new Promise((r) => setTimeout(r, 20));
    assert(document.activeElement === name, 'focus first invalid profile field');
    assert(name.getAttribute('aria-invalid') === 'true', 'profile name invalid');
    // save profile
    name.value = 'Jordan A. Rivera';
    name.dispatchEvent(new window.Event('input', { bubbles: true }));
    document.querySelector('#profile-form').dispatchEvent(new window.Event('submit', { bubbles: true, cancelable: true }));
    await new Promise((r) => setTimeout(r, 20));
    assert(document.querySelector('#profile-name').textContent === 'Jordan A. Rivera', 'profile display updated');
    assert(document.querySelector('#profile-status').textContent.includes('saved'), 'profile status');
    // drop
    const dropButton = document.querySelector('[data-drop="PSY 101"]');
    assert(!!dropButton, 'drop button exists');
    assert(dropButton.getAttribute('aria-label').startsWith('Drop PSY 101'), 'drop accessible name');
    dropButton.click();
    await new Promise((r) => setTimeout(r, 20));
    const dd = document.querySelector('#drop-dialog');
    assert(dd.hasAttribute('open'), 'drop dialog opens');
    assert(document.activeElement === document.querySelector('#drop-cancel'), 'drop cancel focused');
    assert(document.querySelector('#drop-description').textContent.includes('PSY 101'), 'drop desc course');
    document.querySelector('#drop-confirm').click();
    await new Promise((r) => setTimeout(r, 30));
    assert(document.querySelectorAll('#registered-tbody tr').length === 1, 'row removed after drop');
    assert(document.querySelector('#registered-status').textContent.includes('PSY 101'), 'drop status');
    assert(document.activeElement === document.querySelector('#registered-heading'), 'focus moves to heading after drop');
    console.log('PROFILE OK, errors:', errors);
    await runAxe('profile', window);
  }
})().catch((e) => {
  console.error(e.stack || e);
  process.exit(1);
});
