const { chromium } = require('playwright');
const fs = require('fs');
const axeSource = fs.readFileSync(require.resolve('axe-core/axe.min.js'), 'utf8');
const BASE = 'http://127.0.0.1:8123/';

function assert(cond, msg) {
  if (!cond) throw new Error('ASSERT FAILED: ' + msg);
}

async function checkPage(browser, url, label, viewport) {
  const page = await browser.newPage({ viewport: viewport || { width: 1280, height: 900 } });
  const errors = [];
  page.on('console', (msg) => { if (msg.type() === 'error') errors.push('console: ' + msg.text()); });
  page.on('pageerror', (err) => errors.push('pageerror: ' + err.message));
  await page.goto(BASE + url, { waitUntil: 'networkidle' });
  await page.addScriptTag({ content: axeSource });
  const results = await page.evaluate(async () => {
    return await axe.run(document, {
      runOnly: { type: 'tag', values: ['wcag2a', 'wcag2aa', 'wcag21a', 'wcag21aa', 'wcag22aa', 'best-practice'] }
    });
  });
  if (results.violations.length) {
    console.log('\nAXE ' + label + ' violations:');
    for (const v of results.violations) {
      console.log('-', v.id, '|', v.impact, '|', v.help);
      for (const n of v.nodes.slice(0, 6)) {
        console.log('   ', n.target.join(' '), '::', n.failureSummary.replace(/\n/g, ' ').slice(0, 350));
      }
    }
  } else {
    console.log('AXE ' + label + ': no violations');
  }
  assert(errors.length === 0, label + ' console errors: ' + errors.join(' | '));
  return page;
}

(async () => {
  const browser = await chromium.launch();

  // Desktop pages
  for (const [file, label] of [['index.html','home'],['courses.html','catalog'],['register.html','register'],['profile.html','profile']]) {
    const page = await checkPage(browser, file, label);
    const overflow = await page.evaluate(() => document.documentElement.scrollWidth - document.documentElement.clientWidth);
    assert(overflow <= 1, label + ' desktop horizontal overflow ' + overflow);
    if (label === 'home') {
      await page.screenshot({ path: '/tmp/nbu-test/home-desktop.png', fullPage: true });
    }
    if (label === 'catalog') {
      await page.screenshot({ path: '/tmp/nbu-test/catalog-desktop.png', fullPage: true });
    }
    if (label === 'register') {
      await page.screenshot({ path: '/tmp/nbu-test/register-desktop.png', fullPage: true });
    }
    if (label === 'profile') {
      await page.screenshot({ path: '/tmp/nbu-test/profile-desktop.png', fullPage: true });
    }
    await page.close();
  }

  // Mobile viewport (320px)
  for (const [file, label] of [['index.html','home'],['courses.html','catalog'],['register.html','register'],['profile.html','profile']]) {
    const page = await checkPage(browser, file, label + '-320', { width: 320, height: 720 });
    const overflow = await page.evaluate(() => document.documentElement.scrollWidth - document.documentElement.clientWidth);
    assert(overflow <= 1, label + ' 320px horizontal overflow ' + overflow);
    if (label === 'home') {
      await page.screenshot({ path: '/tmp/nbu-test/home-320.png', fullPage: true });
    }
    if (label === 'register') {
      await page.screenshot({ path: '/tmp/nbu-test/register-320.png', fullPage: true });
    }
    if (label === 'profile') {
      await page.screenshot({ path: '/tmp/nbu-test/profile-320.png', fullPage: true });
    }
    await page.close();
  }

  // Mobile menu behaviour
  {
    const page = await browser.newPage({ viewport: { width: 320, height: 720 } });
    await page.goto(BASE + 'index.html', { waitUntil: 'networkidle' });
    const toggle = page.locator('.nav-toggle');
    assert(await toggle.isVisible(), 'mobile toggle visible');
    await toggle.click();
    assert(await toggle.getAttribute('aria-expanded') === 'true', 'mobile menu expands');
    assert(await page.locator('#primary-nav').isVisible(), 'mobile nav visible');
    await page.keyboard.press('Escape');
    assert(await toggle.getAttribute('aria-expanded') === 'false', 'mobile menu collapses on escape');
    assert(await toggle.evaluate(el => document.activeElement === el), 'escape returns focus to toggle');
    await page.close();
  }

  // Catalog real interactions
  {
    const page = await browser.newPage({ viewport: { width: 1280, height: 900 } });
    await page.goto(BASE + 'courses.html?q=calculus', { waitUntil: 'networkidle' });
    assert(await page.locator('#course-search').inputValue() === 'calculus', 'query param prefills search');
    assert(await page.locator('#course-grid .course-card').count() === 1, 'search query result');
    await page.locator('#reset-filters').click();
    assert(await page.locator('#course-grid .course-card').count() === 18, 'reset shows 18');
    await page.locator('#filter-availability').selectOption('full');
    assert(await page.locator('#course-grid .course-card').count() === 2, 'full courses count 2');
    await page.locator('#filter-department').selectOption('Computer Science');
    assert(await page.locator('#course-grid .course-card').count() === 1, 'full CSE course count 1');
    const status = await page.locator('#results-status').textContent();
    assert(status.includes('1 of 18'), 'status count after filters');
    await page.close();
  }

  // Registration flow and persistence
  {
    const context = await browser.newContext({ viewport: { width: 1280, height: 900 } });
    const page = await context.newPage();
    const errors = [];
    page.on('console', (msg) => { if (msg.type() === 'error') errors.push(msg.text()); });
    page.on('pageerror', (err) => errors.push(err.message));
    await page.goto(BASE + 'register.html', { waitUntil: 'networkidle' });
    await page.locator('#reg-name').fill('');
    await page.locator('button[type="submit"]').click();
    assert(await page.locator('#error-summary').isVisible(), 'error summary visible');
    assert(await page.evaluate(() => document.activeElement.id) === 'error-summary', 'error summary focused');
    assert(await page.locator('#reg-name').getAttribute('aria-invalid') === 'true', 'name invalid');
    await page.locator('#reg-name').fill('Jordan Rivera');
    await page.locator('#reg-course').selectOption('CSE 216');
    await page.locator('button[type="submit"]').click();
    assert(await page.locator('#confirm-dialog').isVisible(), 'confirm dialog visible');
    assert(await page.evaluate(() => document.activeElement.id) === 'confirm-cancel', 'cancel initially focused');
    await page.screenshot({ path: '/tmp/nbu-test/register-dialog.png' });
    await page.keyboard.press('Escape');
    assert(!(await page.locator('#confirm-dialog').isVisible()), 'escape closes dialog');
    assert(await page.evaluate(() => document.activeElement.id) === 'confirm-submit' || await page.evaluate(() => document.activeElement.type === 'submit'), 'focus returns to opener after escape');
    await page.locator('button[type="submit"]').click();
    await page.locator('#confirm-submit').click();
    await page.waitForTimeout(100);
    assert(await page.locator('#reg-status').textContent().then(t => t.includes('CSE 216')), 'success status');
    await page.goto(BASE + 'profile.html', { waitUntil: 'networkidle' });
    assert(await page.locator('#registered-tbody tr').count() === 3, 'registration persisted to profile');
    const rowsText = await page.locator('#registered-tbody').textContent();
    assert(rowsText.includes('CSE 216'), 'CSE 216 in profile');
    assert(errors.length === 0, 'registration console errors: ' + errors.join(' | '));
    await context.close();
  }

  // Profile update and drop
  {
    const page = await browser.newPage({ viewport: { width: 1280, height: 900 } });
    await page.goto(BASE + 'profile.html', { waitUntil: 'networkidle' });
    await page.locator('#profile-name-input').fill('Jordan A. Rivera');
    await page.locator('#profile-form button[type="submit"]').click();
    assert(await page.locator('#profile-name').textContent() === 'Jordan A. Rivera', 'profile displays saved name');
    assert(await page.locator('#profile-status').textContent().then(t => t.includes('saved')), 'profile status');
    const drop = page.locator('[data-drop="PSY 101"]');
    await drop.click();
    assert(await page.locator('#drop-dialog').isVisible(), 'drop dialog visible');
    assert(await page.evaluate(() => document.activeElement.id) === 'drop-cancel', 'drop cancel focused');
    await page.locator('#drop-confirm').click();
    await page.waitForTimeout(100);
    assert(await page.locator('#registered-tbody tr').count() === 1, 'drop removes row');
    assert(await page.evaluate(() => document.activeElement.id) === 'registered-heading', 'focus after drop to heading');
    assert(await page.locator('#registered-status').textContent().then(t => t.includes('PSY 101')), 'drop status');
    await page.close();
  }

  // 200% zoom / large text-ish check (CSS zoom to emulate)
  {
    const page = await browser.newPage({ viewport: { width: 640, height: 800 } });
    await page.goto(BASE + 'courses.html', { waitUntil: 'networkidle' });
    await page.evaluate(() => { document.documentElement.style.fontSize = '200%'; });
    await page.waitForTimeout(100);
    const overflow = await page.evaluate(() => document.documentElement.scrollWidth - document.documentElement.clientWidth);
    assert(overflow <= 1, '200% text zoom horizontal overflow ' + overflow);
    await page.close();
  }

  await browser.close();
  console.log('BROWSER TESTS PASSED');
})().catch((e) => {
  console.error(e.stack || e);
  process.exit(1);
});
