 search:'<input type=search>',
 text:'<input type=text>',
 email:'<input type=email>',
 textarea:'<textarea></textarea>',
 autocomplete:'<input type=text autocomplete=name>',
 placeholder:'<input type=text placeholder=hi>',
 button:'<button>Hi</button>',
 select:'<select><option>a</option></select>',
 label:'<label for=x>X</label><input id=x type=search>'
};
(async()=>{
 for (const [name,content] of Object.entries(variants)) {
  let b;
  try {
   b=await chromium.launch();
   const p=await b.newPage();
   await p.setContent('<!DOCTYPE html><html lang="en"><body>'+content+'</body></html>',{waitUntil:'load',timeout:8000});
   console.log('OK',name);
  } catch(e){console.log('ERR',name,e.message.split('\n')[0]);}
  try{if(b) await b.close();}catch(e){}
 }
})();
