const {chromium}=require('playwright');
(async()=>{
 const b=await chromium.launch();
 for (const file of ['index.html','profile.html']) {
  const p=await b.newPage({viewport:{width:320,height:900}});
  await p.goto('http://127.0.0.1:8123/'+file,{waitUntil:'networkidle'});
  await p.evaluate(()=>{document.documentElement.style.fontSize='200%'});
  await p.waitForTimeout(100);
  const out=await p.evaluate(()=>{
   const vw=document.documentElement.clientWidth;
   return [...document.querySelectorAll('body *')].map(el=>{
    const r=el.getBoundingClientRect();
    return {tag:el.tagName, cls:typeof el.className==='string'?el.className:'', id:el.id, right:Math.round(r.right), left:Math.round(r.left), width:Math.round(r.width), text:(el.textContent||'').trim().slice(0,50)};
   }).filter(x=>x.right>vw+1 || x.left<-1).slice(0,30);
  });
  console.log(file, out);
  await p.close();
 }
 await b.close();
})().catch(e=>{console.error(e);process.exit(1)});
