input.command:
cat > /tmp/nbu-test/state-axe.js <<'JS'
const { chromium } = require('playwright');
const fs = require('fs');
const axeSource = fs.readFileSync(require.resolve('axe-core/axe.min.js'), 'utf8');
const BASE = 'http://127.0.0.1:8123/';
async function axe(page, label) {
  await page.addScriptTag({ content: axeSource });
  const results = await page.evaluate(async () => await axe.run(document, {
    runOnly: { type: 'tag', values: ['wcag2a','wcag2aa','wcag21a','wcag21aa','wcag22aa','best-practice'] }
  }));
  if (results.violations.length) {
    console.log('\nAXE ' + label + ' violations:');
    for (const v of results.violations) {
      console.log('-', v.id, '|', v.impact, '|', v.help);
      for (const n of v.nodes.slice(0, 5)) console.log('   ', n.target.join(' '), '::', n.failureSummary.replace(/\n/g,' ').slice(0,300));
    }
  } else console.log('AXE ' + label + ': no violations');
}
(async()=>{
 const b=await chromium.launch();
 // error state
 {
  const p=await b.newPage({viewport:{width:1280,height:900}});
  await p.goto(BASE+'register.html',{waitUntil:'networkidle'});
  await p.locator('#reg-name').fill('');
  await p.locator('button[type=submit]').click();
  await axe(p,'register-error-state');
  await p.close();
 }
 // dialog state
 {
  const p=await b.newPage({viewport:{width:1280,height:900}});
  await p.goto(BASE+'register.html',{waitUntil:'networkidle'});
  await p.locator('#reg-course').selectOption('CSE 216');
  await p.locator('button[type=submit]').click();
  await axe(p,'register-confirm-dialog');
  await p.close();
 }
 // drop dialog
 {
  const p=await b.newPage({viewport:{width:1280,height:900}});
  await p.goto(BASE+'profile.html',{waitUntil:'networkidle'});
  await p.locator('[data-drop="PSY 101"]').click();
  await axe(p,'profile-drop-dialog');
  await p.close();
 }
 // catalog empty state
 {
  const p=await b.newPage({viewport:{width:1280,height:900}});
  await p.goto(BASE+'courses.html',{waitUntil:'networkidle'});
  await p.locator('#course-search').fill('zzzz-no-results');
  await p.waitForTimeout(300);
  await axe(p,'catalog-empty-state');
  await p.close();
 }
 // mobile menu open
 {
  const p=await b.newPage({viewport:{width:320,height:720}});
  await p.goto(BASE+'index.html',{waitUntil:'networkidle'});
  await p.locator('.nav-toggle').click();
  await axe(p,'home-mobile-menu-open');
  await p.close();
 }
 // empty registered state
 {
  const p=await b.newPage({viewport:{width:1280,height:900}});
  await p.goto(BASE+'profile.html',{waitUntil:'networkidle'});
  await p.evaluate(()=>localStorage.setItem('nbu-registration-v1',JSON.stringify({profile:{name:'Jordan Rivera',email:'jordan.rivera@northbridge.edu',studentId:'20261408',program:'Computer Science',year:'2'},registrations:[]})));
  await p.reload({waitUntil:'networkidle'});
  await axe(p,'profile-empty-schedule');
  await p.close();
 }
 await b.close();
 console.log('STATE AXE DONE');
})().catch(e=>{console.error(e.stack||e);process.exit(1)});
JS
